/* level.js — mapa em grade + builder Three.js. Zonas: entrada, salão, forja,
 * catacumbas, armadilha, arena. Símbolos:
 * # parede  . chão  P spawn jogador  D porta (E)  E saída (E)
 * H saúde  A armadura  m munição 2/3/4 armas  i imp  d demon  B baron  x secreto
 * ~ lava (dano)  L tocha
 */
import * as THREE from 'three';
import C from './constants.js';

const W = 44, H = 36;
const RAW = [
'############################################',
'#........#.........i#...........#........d.#',
'####.###.#..###..####..###.###..#..####..#.#',
'#..L..#.#..#2....#.....#.....#...#.....#...#',
'#..H..###..#.###.#..D..###.###.#..H...#...#',
'#.......P....L..#..i..#............#.......#',
'#..####..###..D..#######..#.#####.#..###..###',
'#.....#.....D.....i..#....#.....#.#........#',
'###.###..###..######.#..###.....#.########.#',
'#...#.L.......#....#.#....#..H..#........#.#',
'#..H.#..####..#.D..#..#####..##.#..#####....#',
'#....#..#..m..#....#..#....#....#..#....#d.##',
'#....D..#......#####..####..####..###..#####',
'#..###..#mmmm#.....#...........#......m..#.#',
'#.....#..####..##.###..#########..#####...#.#',
'#..H..D.....i..#.....#.....#.........H....#.#',
'####...#####..##.#####..###..#####....####.#',
'#...#Ad.....#....#....#.....#.....#..####..#',
'#...#####..###..#.#..#..m#..A.#..###.....#.#',
'#.......#.i..m..#.#.#....#....#..#......d#.#',
'#####..###.#####.##.#.###########.####....#.#',
'#...D.....3#..L..#..#............#....#####.#',
'#...##.####.#.#####.#.###.#####..#.##....#.#',
'#.........#.#.......#.#.......#..#.#..##..#.#',
'#.###########.#####.#.#####.#.###.#.######..#',
'#...#........#.....#d#.....#.....#.......#d.#',
'#...####..###..####.#..#####..##.#.#######.#',
'#...#......#.......#...#........#.....#.....#',
'#..#####..#####.###.#####..#######.#####..###',
'#..E..#L....4#.......#......#.....#........#',
'#####..##..####..####..###..###..######..####',
'#.........................#..............E...#',
'#..###..###..###..###..#####..##..####....#',
'#..#...B....B....B..L.B....#..#........H..x#',
'#..###..###..###..###..####..##..####....#',
'############################################',
];

export function buildLevel(engine) {
  // Normaliza: linhas para W via padEnd + fecha borda
  const rows = RAW.map((r) => r.padEnd(W, '#').slice(0, W).split(''));
  for (let c = 0; c < W; c++) { rows[0][c] = '#'; rows[H - 1][c] = '#'; }
  for (let r = 0; r < H; r++) { rows[r][0] = '#'; rows[r][W - 1] = '#'; }

  const { scene } = engine;
  const group = new THREE.Group();
  scene.add(group);

  /* Zonas por região (6): entrada, salao, forja, catacumbas, armadilha, arena */
  const zone = (r, c) => {
    if (r >= 28) return 'arena';
    if (r >= 24 && c >= 29) return 'armadilha';
    if (c >= 29) return 'catacumbas';
    if (c >= 18 && c < 29) return 'forja';
    if (c >= 8 && c < 18) return 'salao';
    return 'entrada';
  };
  const ZCOLOR = {
    entrada: 0x6b6b6b, salao: 0x9c3b3b, forja: 0x7a4a2a,
    catacumbas: 0x5a4a3a, armadilha: 0x8a8a8a, arena: 0x3a3a5a,
  };
  const FCOLOR = {
    entrada: 0x5a5a5a, salao: 0x6a3a3a, forja: 0x4a3220,
    catacumbas: 0x423830, armadilha: 0x6a6a6a, arena: 0x2e2e42,
  };

  const wallMat = {}; const floorMat = {};
  for (const z in ZCOLOR) { wallMat[z] = new THREE.MeshStandardMaterial({ color: ZCOLOR[z], roughness: 0.9 }); floorMat[z] = new THREE.MeshStandardMaterial({ color: FCOLOR[z], roughness: 1 }); }
  const doorMat = new THREE.MeshStandardMaterial({ color: 0xcc8833, metalness: 0.4, roughness: 0.5 });
  const exitMat = new THREE.MeshStandardMaterial({ color: 0x33cc55, emissive: 0x228833, emissiveIntensity: 0.6 });
  const lavaMat = new THREE.MeshStandardMaterial({ color: 0xff4400, emissive: 0xff2200, emissiveIntensity: 0.8 });
  const techMat = new THREE.MeshStandardMaterial({ color: 0x222233, emissive: 0x112233, emissiveIntensity: 0.4 });
  const box1 = new THREE.BoxGeometry(1, 1, 1);

  const cells = {};       // "r,c" -> { solid, door?, secret?, exit?, lava? }
  const doors = []; const secrets = []; const exits = [];
  const pickups = []; const enemies = [];
  let playerSpawn = { x: 1.5, z: 1.5 };
  const visited = Array.from({ length: H }, () => new Array(W).fill(false));

  for (let r = 0; r < H; r++) for (let c = 0; c < W; c++) {
    const ch = rows[r][c];
    const key = `${r},${c}`;
    const x = c + 0.5, z = r + 0.5;
    const zc = zone(r, c);
    /* chão (sempre, menos parede sólida) */
    const floor = new THREE.Mesh(box1, floorMat[zc]);
    floor.scale.set(1.02, 0.06, 1.02); floor.position.set(x, -0.03, z);
    group.add(floor);

    if (ch === '#') {
      const wall = new THREE.Mesh(box1, wallMat[zc]);
      wall.position.set(x, 1.5, z);
      group.add(wall);
      cells[key] = { solid: true };
    } else if (ch === 'D') {
      const d = new THREE.Mesh(box1, doorMat);
      d.position.set(x, 1.2, z); d.scale.set(0.92, 2.4, 0.92);
      group.add(d);
      const door = { mesh: d, open: false, t: 1, r, c };
      doors.push(door);
      cells[key] = { solid: true, door };
    } else if (ch === 'E') {
      const e = new THREE.Mesh(box1, exitMat);
      e.position.set(x, 0.6, z); e.scale.set(0.5, 1.1, 0.5);
      group.add(e);
      exits.push({ r, c, mesh: e });
      cells[key] = { solid: false, exit: true };
    } else if (ch === 'x') {
      const s = new THREE.Mesh(box1, wallMat[zc]);
      s.position.set(x, 1.5, z);
      group.add(s);
      const sec = { mesh: s, open: false, r, c, secret: true };
      secrets.push(sec);
      cells[key] = { solid: true, secret: sec };
    } else if (ch === '~') {
      const l = new THREE.Mesh(box1, lavaMat);
      l.position.set(x, 0.03, z); l.scale.set(0.96, 0.08, 0.96);
      group.add(l);
      cells[key] = { solid: false, lava: true };
    } else if ('HAm234'.includes(ch)) {
      const p = new THREE.Mesh(box1, techMat);
      const colors = { H: 0xff3333, A: 0x3366ff, m: 0xffcc33, '2': 0xcc8844, '3': 0x44cc88, '4': 0xcc4444 };
      p.material = new THREE.MeshStandardMaterial({ color: colors[ch], emissive: colors[ch], emissiveIntensity: 0.5 });
      p.position.set(x, 0.4, z); p.scale.set(0.5, 0.5, 0.5);
      group.add(p);
      const type = ch === 'H' ? 'health' : ch === 'A' ? 'armor' : ch === 'm' ? 'ammo' : ch === '2' ? 'shotgun' : ch === '3' ? 'chaingun' : 'rocket';
      pickups.push({ type, r, c, mesh: p, taken: false, x, z });
      cells[key] = { solid: false };
    } else if (ch === 'i' || ch === 'd' || ch === 'B') {
      enemies.push({ type: ch === 'i' ? 'imp' : ch === 'd' ? 'demon' : 'baron', r, c, x, z });
      cells[key] = { solid: false };
    } else if (ch === 'P') {
      playerSpawn = { x, z };
      cells[key] = { solid: false };
    } else if (ch === 'L') {
      cells[key] = { solid: false };
    } else {
      cells[key] = { solid: false };
    }
  }

  /* Iluminação: hemisférica (chão/paredes) + ambiente de preenchimento + tochas (L) como PointLights */
  const hemi = new THREE.HemisphereLight(0x8899bb, 0x445566, 0.9);
  scene.add(hemi);
  const ambient = new THREE.AmbientLight(0x404050, 0.45);
  scene.add(ambient);
  const torches = [];
  for (let r = 0; r < H; r++) for (let c = 0; c < W; c++) {
    if (rows[r][c] === 'L') {
      const light = new THREE.PointLight(0xffaa55, 1.5, 14, 1.8);
      light.position.set(c + 0.5, 2.2, r + 0.5);
      scene.add(light);
      const flame = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 6), new THREE.MeshBasicMaterial({ color: 0xffaa55 }));
      flame.position.set(c + 0.5, 1.6, r + 0.5);
      group.add(flame);
      torches.push(light);
    }
  }

  /* Teto único (visão interna) */
  const ceil = new THREE.Mesh(new THREE.PlaneGeometry(W, H), new THREE.MeshBasicMaterial({ color: 0x1a1a24, side: THREE.BackSide }));
  ceil.rotation.x = -Math.PI / 2; ceil.position.set(W / 2, 3.4, H / 2);
  scene.add(ceil);

  const isSolid = (r, c) => {
    if (r < 0 || c < 0 || r >= H || c >= W) return true;
    const cell = cells[`${r},${c}`];
    if (!cell) return false;
    if (cell.door && cell.door.open) return false; // porta aberta = passável
    if (cell.secret && cell.secret.open) return false;
    return cell.solid;
  };
  const visit = (r, c) => { if (r >= 0 && c >= 0 && r < H && c < W) visited[r][c] = true; };

  const level = {
    W, H, rows, cells, doors, secrets, exits, pickups, enemies,
    playerSpawn, visited, torches,
    isSolid, visit,
    playerPos: null,
    openDoor(door) { if (!door.open) { door.open = true; door.t = 0; door.mesh.material = new THREE.MeshStandardMaterial({ color: 0x664422, transparent: true, opacity: 0.35 }); } },
    openSecret(sec) { if (!sec.open) { sec.open = true; sec.mesh.visible = false; } },
    update(dt) {
      /* anima portas abrindo */
      for (const d of doors) if (d.open && d.t < 1) { d.t = Math.min(1, d.t + dt * C.LEVEL.doorSpeed); d.mesh.position.y = 1.2 - d.t * 2.0; }
      for (const t of torches) { t.intensity = 1.2 + Math.sin(performance.now() * 0.008 + t.position.x * 7) * 0.3; }
    },
  };
  return level;
}

/* Registrar como módulo — init constrói o nível na ordem correta (antes do player) */
let built = null;
window.__registerMod('level', {
  init(game, engine) {
    if (!built) { built = buildLevel(engine); game.level = built; }
  },
  update(dt, game) { if (built) built.update(dt); },
});

/* weapons.js — arsenal (pistola/shotgun/chaingun/rocket), munição, hitscan + foguete.
 * Popula window.__game.weapons = { owned, ammo, current, fire(), update() }.
 */
import * as THREE from 'three';
import C from './constants.js';

const ray = new THREE.Raycaster();
const tmpDir = new THREE.Vector3();

/* foguetes (projéteis do jogador com splash) */
const rockets = [];

function makeWeaponState(game) {
  const w = {
    owned: ['pistol'],
    current: 'pistol',
    ammo: { bullet: 80, shell: 12, rocket: 4 },
    fireCd: 0,
    spin: 0, // spinup do chaingun
    fire() {
      const cfg = C.WEAPONS[w.current];
      if (cfg.ammoType !== 'pistol' && w.ammo[cfg.ammoType] <= 0) {
        game.events.onNoAmmo?.();
        return;
      }
      game.stats.shots++;
      game.events.onShot?.(w.current);

      if (w.current === 'rocket') {
        const cfgW = C.WEAPONS.rocket;
        const cam = game.cameraDir || new THREE.Vector3(0, 0, -1);
        const r = new THREE.Mesh(rocketGeo, rocketMat);
        game.scene.add(r);
        r.position.copy(cam.origin.clone().add(cam.dir.clone().multiplyScalar(0.5)));
        r.userData.vel = cam.dir.clone().multiplyScalar(cfgW.projSpeed);
        rockets.push(r);
        w.ammo.rocket--;
        w.fireCd = cfgW.rate;
        return;
      }

      /* hitscan: 1 raio (pistol/chaingun) ou N pellets (shotgun) */
      const cfgW = C.WEAPONS[w.current];
      const pellets = cfgW.pellets || 1;
      const cam = game.cameraDir;
      for (let i = 0; i < pellets; i++) {
        const spread = (cfgW.spread || 0.02) + (w.current === 'chaingun' ? w.spin * cfgW.spreadGrow : 0);
        tmpDir.copy(cam.dir);
        tmpDir.x += (Math.random() - 0.5) * spread * 2;
        tmpDir.y += (Math.random() - 0.5) * spread * 2;
        tmpDir.z += (Math.random() - 0.5) * spread * 2;
        tmpDir.normalize();
        ray.set(cam.origin, tmpDir);
        ray.far = 60;
        /* testa contra inimigos vivos */
        let best = null, bestD = Infinity;
        for (const e of game.enemies) {
          if (e.dead) continue;
          ray.intersectObject(e.mesh, true).forEach((hit) => {
            if (hit.distance < bestD) { bestD = hit.distance; best = e; }
          });
        }
        if (best) {
          best.takeDamage(cfgW.damage);
          game.stats.hits++;
          game.events.onHit?.();
        }
      }
      if (cfgW.ammoType !== 'pistol') w.ammo[cfgW.ammoType] -= 1;
      w.fireCd = cfg.rate;
    },
    switchTo(name) {
      if (w.owned.includes(name)) { w.current = name; w.spin = 0; game.events.onSwitch?.(name); }
    },
    update(dt, engine) {
      w.fireCd = Math.max(0, w.fireCd - dt);
      const firing = engine.input.keys.has('Mouse0');
      const cfg = C.WEAPONS[w.current];
      if (firing && w.fireCd <= 0 && w.current !== 'chaingun') w.fire();
      if (w.current === 'chaingun') {
        w.spin = firing ? Math.min(1, w.spin + dt / cfg.spinup) : 0;
        if (firing && w.fireCd <= 0) w.fire();
      }
    },
  };
  return w;
}

/* foguete: geometria/material compartilhados */
const rocketGeo = new THREE.CylinderGeometry(0.08, 0.08, 0.4, 6);
const rocketMat = new THREE.MeshStandardMaterial({ color: 0xcccccc, emissive: 0xff4400, emissiveIntensity: 0.6 });

window.__registerMod('weapons', {
  init(game, engine) {
    game.scene = engine.scene;
    game.weapons = makeWeaponState(game);
    game.weapons._rockets = rockets;
    game.cameraDirUpdate = () => {
      game.cameraDir = {
        origin: engine.camera.position.clone(),
        dir: new THREE.Vector3().setFromEuler(engine.camera.rotation),
      };
    };
  },
  update(dt, game, engine) {
    if (!game.player || !game.weapons) return;
    game.cameraDirUpdate();
    game.weapons.update(dt, engine);

    /* teclas 1-4 trocam arma */
    const digit = ['Digit1', 'Digit2', 'Digit3', 'Digit4'].find((d) => engine.wasPressed(d));
    if (digit) {
      const names = ['pistol', 'shotgun', 'chaingun', 'rocket'];
      game.weapons.switchTo(names[+digit[5] - 1]);
    }

    /* foguetes: movimento + splash */
    for (let i = rockets.length - 1; i >= 0; i--) {
      const r = rockets[i];
      r.position.addScaledVector(r.userData.vel, dt);
      const cell = game.level.cells[`${Math.floor(r.position.z)},${Math.floor(r.position.x)}`];
      const hitWall = cell && cell.solid;
      const hitEnemy = game.enemies.some((e) => !e.dead && e.pos.distanceTo(r.position) < 0.8);
      if (hitWall || hitEnemy || r.position.y < 0) {
        /* explosão: splash nos inimigos + dano ao próprio jogador (selfDamage) */
        const cfg = C.WEAPONS.rocket;
        for (const e of game.enemies) {
          if (e.dead) continue;
          const d = e.pos.distanceTo(r.position);
          if (d < cfg.splash) { e.takeDamage(cfg.damage * (1 - d / cfg.splash) + 1); game.stats.hits++; }
        }
        const pDist = game.player.pos.distanceTo(r.position);
        if (pDist < cfg.splash) game.damagePlayer(cfg.damage * cfg.selfDamage * (1 - pDist / cfg.splash), 'foguete');
        game.events.onExplosion?.(r.position);
        engine.scene.remove(r);
        rockets.splice(i, 1);
      }
    }
  },
});

/* enemies.js — spawn, IA (chase/ataque), projéteis inimigos, dano ao jogador.
 * Popula window.__game.enemies (array de { mesh, hp, type, pos, takeDamage }).
 */
import * as THREE from 'three';
import C from './constants.js';

const AGGRO = 16;
const bodyGeo = new THREE.BoxGeometry(0.7, 1.1, 0.7);
const eyeGeo = new THREE.SphereGeometry(0.06, 6, 4);
const projGeo = new THREE.SphereGeometry(0.14, 8, 6);
const eyeMat = new THREE.MeshBasicMaterial({ color: 0xff2200 });

function makeEnemyMesh(type, scale) {
  const cfg = C.ENEMIES[type];
  const g = new THREE.Group();
  const body = new THREE.Mesh(bodyGeo, new THREE.MeshStandardMaterial({ color: cfg.color, roughness: 0.85 }));
  body.scale.set(scale, scale, scale);
  body.position.y = 0.55 * scale;
  g.add(body);
  for (const sx of [-0.16, 0.16]) {
    const eye = new THREE.Mesh(eyeGeo, eyeMat);
    eye.position.set(sx * scale, 0.72 * scale, 0.36 * scale);
    g.add(eye);
  }
  return g;
}

let spawned = false;
const projectiles = [];

function spawnProjectile(scene, from, to, cfg) {
  const p = new THREE.Mesh(projGeo, new THREE.MeshStandardMaterial({ color: 0xffaa33, emissive: 0xff8800, emissiveIntensity: 0.8 }));
  p.position.copy(from);
  const dir = to.clone().sub(from);
  dir.y = 0;
  if (dir.lengthSq() < 0.01) return;
  dir.normalize();
  p.userData.vel = dir.multiplyScalar(cfg.projSpeed);
  p.userData.dmg = cfg.damage;
  p.userData.life = 6;
  scene.add(p);
  projectiles.push(p);
}

window.__registerMod('enemies', {
  update(dt, game, engine) {
    const lvl = game.level;
    if (!lvl || !game.player) return;

    /* spawn único na primeira atualização */
    if (!spawned) {
      for (const s of lvl.enemies) {
        const cfg = C.ENEMIES[s.type];
        const mesh = makeEnemyMesh(s.type, cfg.scale);
        mesh.position.set(s.x, 0, s.z);
        engine.scene.add(mesh);
        game.enemies.push({
          type: s.type, mesh, pos: mesh.position, hp: cfg.hp,
          cooldown: Math.random() * 1,
          takeDamage(dmg) {
            this.hp -= dmg;
            game.events.onHit?.(this, dmg);
            if (this.hp <= 0) {
              this.dead = true;
              mesh.visible = false;
              game.stats.kills++;
              game.events.onKill?.(this);
            }
          },
        });
      }
      spawned = true;
    }

    const player = game.player;
    const pPos = player.pos;

    for (const e of game.enemies) {
      if (e.dead) continue;
      const cfg = C.ENEMIES[e.type];
      const dx = pPos.x - e.pos.x;
      const dz = pPos.z - e.pos.z;
      const dist = Math.hypot(dx, dz);
      e.cooldown -= dt;

      if (dist < AGGRO) {
        const nx = dx / (dist || 1);
        const nz = dz / (dist || 1);

        if (cfg.attackType === 'melee') {
          if (dist > cfg.meleeRange * 0.9) {
            tryMove(e.pos, nx, nz, cfg.speed * dt, lvl);
          } else if (e.cooldown <= 0) {
            e.cooldown = cfg.cooldown;
            game.damagePlayer(cfg.damage, e.type);
            game.events.onEnemyAttack?.(e);
          }
        } else {
          /* ranged: mantém distância na faixa [rangeMin, rangeMax] */
          if (dist > cfg.rangeMax) tryMove(e.pos, nx, nz, cfg.speed * dt, lvl);
          else if (dist < cfg.rangeMin) tryMove(e.pos, -nx, -nz, cfg.speed * dt, lvl);
          else if (e.cooldown <= 0) {
            e.cooldown = cfg.cooldown;
            spawnProjectile(engine.scene, e.pos.clone().add(new THREE.Vector3(0, 1.0, 0)), pPos.clone(), cfg);
          }
        }
        /* olha para o jogador */
        e.mesh.rotation.y = Math.atan2(dx, dz);
      }
    }

    /* projéteis inimigos */
    for (let i = projectiles.length - 1; i >= 0; i--) {
      const p = projectiles[i];
      p.userData.life -= dt;
      p.position.addScaledVector(p.userData.vel, dt);
      const cell = lvl.cells[`${Math.floor(p.position.z)},${Math.floor(p.position.x)}`];
      const hitWall = cell && cell.solid;
      const hitPlayer = p.position.distanceTo(pPos) < 0.7;
      if (hitWall || hitPlayer || p.userData.life <= 0) {
        if (hitPlayer) { game.damagePlayer(p.userData.dmg, 'inimigo'); game.events.onEnemyProjectileHit?.(p.position); }
        engine.scene.remove(p);
        projectiles.splice(i, 1);
      }
    }
  },
});

/* movimento com slide em sólidos */
function tryMove(pos, nx, nz, step, lvl) {
  const tx = pos.x + nx * step;
  const tz = pos.z + nz * step;
  if (!lvl.isSolid(Math.floor(tz), Math.floor(tx))) { pos.x = tx; pos.z = tz; return; }
  if (!lvl.isSolid(Math.floor(pos.z), Math.floor(tx))) { pos.x = tx; return; }
  if (!lvl.isSolid(Math.floor(tz), Math.floor(pos.x))) { pos.z = tz; }
}

/* player.js — movimento, física (AABB contra grade), vida/armadura, dano.
 * game.player = { pos (Vector3), vel, hp, armor, onGround, invuln, alive }
 * window.__game.damagePlayer(dmg, origem) — usado por inimigos/arma/área.
 */
import * as THREE from 'three';
import C from './constants.js';
import { moveVec } from './move.js';

const R = C.PLAYER.radius;
const EYE = C.PLAYER.eye;

let state = null; // { pos, vel, hp, armor, onGround, invuln, alive }

function solidAt(lvl, x, z) {
  return lvl.isSolid(Math.floor(z), Math.floor(x));
}

function collideAxis(lvl, axis, before) {
  /* colisão círculo x grade no eixo axis ('x'|'z') */
  const p = state.pos;
  const r = R;
  if (axis === 'x') {
    const nx = p.x;
    const minZ = Math.min(before.z - r, p.z - r), maxZ = Math.max(before.z + r, p.z + r);
    for (let z = Math.floor(minZ); z <= Math.floor(maxZ); z++) {
      if (solidAt(lvl, nx + Math.sign(nx - before.x || 1) * r, z + 0.5)) {
        p.x = before.x; state.vel.x = 0; return;
      }
    }
  } else {
    for (let x = Math.floor(Math.min(before.x - r, p.x - r)); x <= Math.floor(Math.max(before.x + r, p.x + r)); x++) {
      if (solidAt(lvl, x + 0.5, p.z + Math.sign(p.z - before.z || 1) * r)) {
        p.z = before.z; state.vel.z = 0; return;
      }
    }
  }
}

export function initPlayer(game, engine) {
  const lvl = game.level;
  state = {
    pos: new THREE.Vector3(lvl.playerSpawn.x, EYE, lvl.playerSpawn.z),
    vel: new THREE.Vector3(),
    hp: C.PLAYER.healthMax,
    armor: 0,
    onGround: true,
    invuln: 0,
    alive: true,
  };
  engine.camera.position.copy(state.pos);
  engine.camera.rotation.set(0, C.PLAYER.spawnYaw, 0);
  game.player = state;
  return state;
}

export function getPlayer() { return state; }

window.__registerMod('player', {
  init(game, engine) {
    if (!state) initPlayer(game, engine);
  },
  update(dt, game, engine) {
    if (!state) return;
    if (!state.alive) { engine.camera.position.copy(state.pos); return; }

    const inp = engine.input.keys;
    const k = (id) => (inp.has(id) ? 1 : 0);
    /* direção no espaço do mundo, relativa à yaw da câmera (YXZ) */
    const yaw = engine.camera.rotation.y;
    let ix = k('KeyD') - k('KeyA');
    let iz = k('KeyS') - k('KeyW');
    const run = inp.has('ShiftLeft') || inp.has('ShiftRight');
    const speed = run ? C.PLAYER.run : C.PLAYER.walk;
    const mv = moveVec(yaw, ix, iz);
    const len = Math.hypot(mv.x, mv.z);
    const mul = len > 0 ? Math.min(1, 1 / len) : 0;

    /* aceleração/fricção (smoothing exponencial simples) */
    const accel = C.PLAYER.accel * dt;
    const air = state.onGround ? 1 : C.PLAYER.airControl;
    state.vel.x += (mv.x * mul * speed - state.vel.x) * Math.min(1, accel * air);
    state.vel.z += (mv.z * mul * speed - state.vel.z) * Math.min(1, accel * air);
    if (len === 0 && state.onGround) {
      const fr = Math.min(1, C.PLAYER.friction * dt);
      state.vel.x *= 1 - fr; state.vel.z *= 1 - fr;
    }

    /* pulo */
    if (engine.wasPressed('Space') && state.onGround) { state.vel.y = C.PLAYER.jumpVel; state.onGround = false; }

    /* gravidade + integração */
    state.vel.y += C.PLAYER.gravity * dt;
    const before = state.pos.clone();
    state.pos.x += state.vel.x * dt;
    collideAxis(game.level, 'x', before);
    state.pos.z += state.vel.z * dt;
    collideAxis(game.level, 'z', before);
    state.pos.y += state.vel.y * dt;

    if (state.pos.y <= EYE) { state.pos.y = EYE; state.vel.y = 0; state.onGround = true; }

    /* lava: dano contínuo */
    const cell = game.level.cells[`${Math.floor(state.pos.z)},${Math.floor(state.pos.x)}`];
    if (cell && cell.lava) damagePlayer(15 * dt, 'lava', game);

    state.invuln = Math.max(0, state.invuln - dt);
    engine.camera.position.copy(state.pos);
    game.level.visit(Math.floor(state.pos.z), Math.floor(state.pos.x));
  },
});

/* ---- API de dano (exposta globalmente p/ inimigos/armas) ---- */
export function damagePlayer(dmg, origem, game) {
  if (!state || !state.alive || state.invuln > 0) return;
  const absorbed = Math.min(state.armor, dmg * C.PLAYER.armorAbsorb);
  state.armor -= absorbed;
  state.hp -= dmg - absorbed;
  state.invuln = C.PLAYER.hitInvuln;
  game.events.onDamage?.(dmg, origem);
  if (state.hp <= 0) {
    state.hp = 0;
    state.alive = false;
    game.events.onDeath?.();
  }
}

window.__game.damagePlayer = (dmg, origem) => window.__game?.player && dmg > 0 && damagePlayer(dmg, origem || 'mundo', window.__game);

/* move.js — transformação de entrada de movimento (local → mundo), pura e testável.
 * Vetor local (ix, iz): +x = direita, +z = trás (convenção câmera Three.js).
 * Aplica a rotação CORRETA R_y(yaw) ao vetor local:
 *   mundo.x = ix*cos(yaw) + iz*sin(yaw)
 *   mundo.z = -ix*sin(yaw) + iz*cos(yaw)
 * (Antes o player.js aplicava R_y(-yaw) — movimento espelhado ao virar,
 *  ex.: com yaw=90° o W andava para trás. Testado em tests/move.test.mjs.)
 */
export function moveVec(yaw, ix, iz) {
  const sy = Math.sin(yaw), cy = Math.cos(yaw);
  return { x: ix * cy + iz * sy, z: -ix * sy + iz * cy };
}

/* minimap.js — minimapa 2D: células visitadas, jogador, inimigos, saída. */
const S = 4; // px por célula
let ctx = null, cw = 0, ch = 0;

window.__registerMod('minimap', {
  init() {
    /* o #minimap do HTML é um div — cria um canvas dentro */
    const host = document.getElementById('minimap');
    const cv = document.createElement('canvas');
    cv.width = 200; cv.height = 150;
    cv.style.width = '100%'; cv.style.height = '100%';
    host.appendChild(cv);
    ctx = cv.getContext('2d');
    cw = cv.width; ch = cv.height;
  },
  update(dt, game) {
    const lvl = game.level;
    if (!ctx || !lvl || !game.player) return;
    const scale = Math.min(cw / lvl.W, ch / lvl.H);
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, cw, ch);

    /* células visitadas (paredes mais claras, chão escuro) */
    for (let r = 0; r < lvl.H; r++) for (let c = 0; c < lvl.W; c++) {
      if (lvl.visited[r][c]) {
        ctx.fillStyle = lvl.isSolid(r, c) ? '#666' : '#222';
        ctx.fillRect(c * scale, r * scale, scale, scale);
      }
    }
    /* inimigos vivos */
    ctx.fillStyle = '#f33';
    for (const e of game.enemies) {
      if (e.dead) continue;
      ctx.fillRect(e.pos.x * scale - 1, e.pos.z * scale - 1, 3, 3);
    }
    /* saídas */
    ctx.fillStyle = '#3c3';
    for (const ex of lvl.exits) ctx.fillRect((ex.c + 0.5) * scale - 1, (ex.r + 0.5) * scale - 1, 3, 3);
    /* jogador */
    ctx.fillStyle = '#fff';
    ctx.fillRect(game.player.pos.x * scale - 2, game.player.pos.z * scale - 2, 4, 4);
  },
});

/* hud.js — DOM HUD: barras de vida/armadura, munição, arma, kills, mensagens, vinheta. */
import C from './constants.js';

const WNAME = { pistol: 'PISTOLA', shotgun: 'SHOTGUN', chaingun: 'CHAINGUN', rocket: 'FOGUETE' };
const AMT = { pistol: '∞', shotgun: 'CARTUCHOS', chaingun: 'BALAS', rocket: 'FOGUETES' };

let vignetteT = 0;
let msgs = [];

window.__registerMod('hud', {
  init(game) {
    game.events.onDamage = (dmg) => { vignetteT = 0.35; };
    game.events.onMessage = (text) => {
      msgs.push({ text, t: 3 });
      if (msgs.length > 4) msgs.shift();
    };
    game.events.onPickup = () => { window.__game.audio?.play('pickup'); };
    game.events.onSecret = () => { window.__game.audio?.play('secret'); window.__game.particles?.burst({ x: 0, y: 0, z: 0 }, 0x33ccff, 20, 5); };
    game.events.onDoor = (open) => { window.__game.audio?.play('door'); };
    game.events.onShot = (name) => { window.__game.audio?.play('shot'); };
    game.events.onHit = () => { window.__game.audio?.play('hit'); };
    game.events.onKill = (e) => { window.__game.audio?.play('kill'); };
    game.events.onExplosion = (pos) => {
      window.__game.audio?.play('explosion');
      window.__game.particles?.burst(pos, 0xffcc33, 30, 6);
    };
    game.events.onEnemyAttack = (e) => { window.__game.audio?.play('hit'); };
    game.events.onEnemyProjectileHit = (pos) => { window.__game.particles?.burst(pos, 0xffaa33, 10, 4); };
  },
  update(dt, game) {
    const pl = game.player;
    const w = game.weapons;
    if (!pl || !w) return;

    /* barras */
    const hpPct = Math.max(0, pl.hp / C.PLAYER.healthMax);
    const arPct = Math.max(0, pl.armor / C.PLAYER.armorMax);
    document.getElementById('health-fill').style.width = `${hpPct * 100}%`;
    document.getElementById('health-value').textContent = Math.ceil(pl.hp);
    document.getElementById('armor-fill').style.width = `${arPct * 100}%`;
    document.getElementById('armor-value').textContent = Math.ceil(pl.armor);

    /* munição / arma */
    const cfg = C.WEAPONS[w.current];
    const ammo = cfg.ammoType === 'pistol' ? '∞' : w.ammo[cfg.ammoType];
    document.getElementById('ammo-count').textContent = ammo;
    document.getElementById('ammo-type').textContent = AMT[w.current];
    document.getElementById('weapon-name').textContent = WNAME[w.current];
    document.getElementById('weapon-key').textContent = String(w.owned.indexOf(w.current) + 1);

    /* kills */
    document.getElementById('kills-value').textContent = game.stats.kills;

    /* mensagens */
    const box = document.getElementById('messages');
    msgs = msgs.filter((m) => { m.t -= dt; return m.t > 0; });
    while (box.children.length < msgs.length) box.appendChild(document.createElement('div')).className = 'msg';
    msgs.forEach((m, i) => { box.children[i].textContent = m.text; box.children[i].style.animation = 'msg-fade 2.4s forwards'; });
    while (box.children.length > msgs.length) box.lastChild.remove();

    /* vinheta de dano */
    if (vignetteT > 0) {
      vignetteT -= dt;
      document.getElementById('damage-vignette').classList.add('active');
    } else {
      document.getElementById('damage-vignette').classList.remove('active');
    }
  },
});

/* main.js — bootstrap, FSM de telas, game loop, registry de módulos.
 * Contrato: cada módulo registra `window.__registerMod(nome, { update?(dt, game, engine) })`.
 * boot() importa os módulos na ordem (registro de inserção = ordem de update).
 */
import * as THREE from 'three';
import C from './constants.js';
import { createEngine } from './engine.js';

const canvas = document.getElementById('game');
const engine = createEngine(canvas);
window.__engine = engine; // debug/instrumentação (mesmo padrão do window.__game)

/* ---------- Estado global ---------- */
window.__game = {
  state: 'MENU',
  events: {},
  stats: { kills: 0, time: 0, secrets: 0, shots: 0, hits: 0 },
  mods: {},
  level: null, player: null, enemies: [], weapons: null,
};
const game = window.__game;
window.__registerMod = (name, api) => { game.mods[name] = api; };

/* ---------- FSM de telas ---------- */
const els = {
  menu: document.getElementById('menu'),
  hud: document.getElementById('hud'),
  paused: document.getElementById('paused'),
  dead: document.getElementById('dead'),
  complete: document.getElementById('complete'),
};
function setState(s) {
  game.state = s;
  for (const id of ['menu', 'hud', 'paused', 'dead', 'complete']) {
    /* ids em minúsculo vs estados em MAIÚSCULO: normaliza via toUpperCase */
    const visible = id.toUpperCase() === s || (id === 'hud' && (s === 'PLAYING' || s === 'PAUSED'));
    els[id].classList.toggle('hidden', !visible);
  }
  if (s === 'PLAYING') engine.requestLock();
  if (s === 'MENU' || s === 'DEAD' || s === 'COMPLETE') engine.exitLock();
}

document.getElementById('start-btn').addEventListener('click', () => setState('PLAYING'));
document.getElementById('restart-btn').addEventListener('click', () => location.reload());
document.getElementById('next-btn').addEventListener('click', () => location.reload());
/* expõe setState para os módulos (game.js usa para DEAD/COMPLETE) */
game.setState = setState;
canvas.addEventListener('click', () => {
  if (game.state === 'MENU' || game.state === 'PAUSED') setState('PLAYING');
});
document.addEventListener('pointerlockchange', () => {
  // ESC sai do pointer lock automaticamente -> pausa
  if (!engine.input.locked && game.state === 'PLAYING') setState('PAUSED');
});

/* ---------- boot: carrega módulos em ordem ---------- */
const MODS = ['level', 'player', 'enemies', 'weapons', 'particles', 'game', 'hud', 'minimap', 'audio'];
async function boot() {
  for (const name of MODS) {
    try { await import(`./${name}.js`); } catch (e) { /* módulo ainda não existe */ }
  }
  /* init de cada módulo registrado (level → player → ... → audio) */
  for (const mod of Object.values(game.mods)) mod.init?.(game, engine);
}

/* ---------- Game loop ---------- */
let last = performance.now();
function frame() {
  requestAnimationFrame(frame);
  const now = performance.now();
  const dt = Math.min((now - last) / 1000, 0.05);
  last = now;

  if (game.state === 'PLAYING') {
    game.stats.time += dt;
    if (engine.wasPressed('Escape') || engine.wasPressed('KeyP')) { setState('PAUSED'); }
    else {
      for (const mod of Object.values(game.mods)) mod.update?.(dt, game, engine);
    }
  } else if (game.state === 'PAUSED') {
    if (engine.wasPressed('KeyP')) setState('PLAYING');
  }

  engine.update(dt);
  engine.render();
}

boot();
frame();

/* engine.js — núcleo Three.js: renderer, cena, câmera, input. pt-BR comentários. */
import * as THREE from 'three';
import C from './constants.js';

export function createEngine(canvas) {
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, C.RENDER.pixelRatioCap));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.shadowMap.enabled = false;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(C.RENDER.background);
  scene.fog = new THREE.Fog(C.RENDER.background, C.RENDER.fogNear, C.RENDER.fogFar);

  const camera = new THREE.PerspectiveCamera(C.RENDER.fov, window.innerWidth / window.innerHeight, C.RENDER.near, C.RENDER.far);
  camera.rotation.order = 'YXZ';

  /* Input: teclas + edge-trigger + mouse (pointer lock) */
  const input = {
    keys: new Set(),
    pressed: new Set(),
    mx: 0, my: 0, scroll: 0,
    locked: false,
    sens: 0.0022,
  };
  const onKeyDown = (e) => {
    if (!input.keys.has(e.code)) input.pressed.add(e.code);
    input.keys.add(e.code);
  };
  const onKeyUp = (e) => input.keys.delete(e.code);
  const onMouseMove = (e) => {
    if (document.pointerLockElement === canvas) { input.mx += e.movementX; input.my += e.movementY; }
  };
  const onWheel = (e) => { input.scroll += Math.sign(e.deltaY); };
  const onMouseDown = () => { input.keys.add('Mouse0'); };
  const onMouseUp = () => { input.keys.delete('Mouse0'); };
  const onLockChange = () => { input.locked = document.pointerLockElement === canvas; };
  const onResize = () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  };
  window.addEventListener('keydown', onKeyDown);
  window.addEventListener('keyup', onKeyUp);
  document.addEventListener('mousemove', onMouseMove);
  window.addEventListener('mousedown', onMouseDown);
  window.addEventListener('mouseup', onMouseUp);
  canvas.addEventListener('wheel', onWheel, { passive: true });
  document.addEventListener('pointerlockchange', onLockChange);
  window.addEventListener('resize', onResize);

  return {
    renderer, scene, camera, input,
    wasPressed(code) {
      if (input.pressed.has(code)) { input.pressed.delete(code); return true; }
      return false;
    },
    requestLock() {
      try { canvas.requestPointerLock(); } catch { /* some browsers rejeitam fora de user gesture — teclas Q/E cobrem */ }
    },
    exitLock() { if (document.pointerLockElement) document.exitPointerLock(); },
    /* Aplica yaw/pitch do mouse + teclas de giro (fallback sem pointer lock) e limpa deltas — chamado 1x/frame */
    update(dt = 0.016) {
      const d = dt > 0 ? dt : 0.016;
      /* giro por teclado: Q/E ou setas (sempre disponíveis, mesmo sem pointer lock) */
      const turn = (input.keys.has('KeyQ') || input.keys.has('ArrowLeft') ? 1 : 0) -
                   (input.keys.has('KeyE') || input.keys.has('ArrowRight') ? 1 : 0);
      if (turn !== 0) camera.rotation.y += turn * C.INPUT.turnSpeed * d;
      camera.rotation.y -= input.mx * input.sens;
      camera.rotation.x -= input.my * input.sens;
      const lim = Math.PI / 2 - 0.05;
      camera.rotation.x = Math.max(-lim, Math.min(lim, camera.rotation.x));
      input.mx = 0; input.my = 0; input.scroll = 0;
    },
    render() { renderer.render(scene, camera); },
  };
}

/* game.js — regras do jogo: pickups, portas/segredos (E), saída, morte/vitória, stats. */
import C from './constants.js';

const RANGE = C.PLAYER.interactRange;
let over = false;

window.__registerMod('game', {
  init(game) {
    game.events.onDeath = () => { if (!over) { over = true; game.setState('DEAD'); } };
    game.events.onExit = () => { if (!over) { over = true; fillStats(game); game.setState('COMPLETE'); } };
  },
  update(dt, game, engine) {
    if (!game.player || !game.level) return;
    if (over) return;

    /* --- pickups por toque --- */
    const p = game.player.pos;
    for (const pk of game.level.pickups) {
      if (pk.taken) continue;
      const dx = p.x - pk.x, dz = p.z - pk.z;
      if (Math.hypot(dx, dz) < 0.9) {
        pk.taken = true;
        pk.mesh.visible = false;
        applyPickup(game, pk.type);
      }
    }

    /* --- interação E: porta / segredo / saída --- */
    if (engine.wasPressed('KeyE')) {
      const lvl = game.level;
      let handled = false;
      for (const d of lvl.doors) {
        if (d.open) continue;
        if (Math.hypot(p.x - (d.c + 0.5), p.z - (d.r + 0.5)) < RANGE) {
          lvl.openDoor(d);
          game.events.onDoor?.(true);
          handled = true;
          break;
        }
      }
      if (!handled) for (const s of lvl.secrets) {
        if (s.open) continue;
        if (Math.hypot(p.x - (s.c + 0.5), p.z - (s.r + 0.5)) < RANGE) {
          lvl.openSecret(s);
          game.stats.secrets++;
          game.events.onSecret?.();
          handled = true;
          break;
        }
      }
      if (!handled) for (const ex of lvl.exits) {
        if (Math.hypot(p.x - (ex.c + 0.5), p.z - (ex.r + 0.5)) < RANGE) {
          if (game.stats.kills >= C.LEVEL.minEnemies) game.events.onExit?.();
          else game.events.onMessage?.('Abata todos os demônios primeiro!');
          break;
        }
      }
    }

    /* --- lava fora da grade --- */
    const cell = game.level.cells[`${Math.floor(p.z)},${Math.floor(p.x)}`];
    if (cell && cell.lava && Math.random() < dt * 2) game.damagePlayer(5, 'lava');
  },
});

function applyPickup(game, type) {
  const pl = game.player;
  const w = game.weapons;
  const msgs = {
    health: () => { pl.hp = Math.min(C.PLAYER.healthMax, pl.hp + C.PICKUPS.health); return '+25 VIDA'; },
    armor: () => { pl.armor = Math.min(C.PLAYER.armorMax, pl.armor + C.PICKUPS.armor); return '+50 ARMADURA'; },
    ammo: () => {
      for (const t of ['bullet', 'shell', 'rocket']) w.ammo[t] += C.PICKUPS.ammoAmounts[t];
      return 'MUNIÇÃO +40/+8/+4';
    },
    shotgun: () => { addWeapon(w, 'shotgun'); return 'SHOTGUN ADQUIRIDA — tecla 2'; },
    chaingun: () => { addWeapon(w, 'chaingun'); return 'CHAINGUN ADQUIRIDA — tecla 3'; },
    rocket: () => { addWeapon(w, 'rocket'); return 'LANÇA-FOGUETES ADQUIRIDO — tecla 4'; },
  };
  msgs[type]?.();
  game.events.onMessage?.(msgs[type]?.() || '');
  game.events.onPickup?.(type);
}
function addWeapon(w, name) {
  if (!w.owned.includes(name)) { w.owned.push(name); w.switchTo(name); }
}

function fillStats(game) {
  const s = game.stats;
  document.getElementById('complete-kills').textContent = s.kills;
  document.getElementById('complete-time').textContent = formatTime(s.time);
  document.getElementById('complete-accuracy').textContent = s.shots > 0 ? `${Math.round((s.hits / s.shots) * 100)}%` : '—';
  document.getElementById('complete-secrets').textContent = s.secrets;
}
function formatTime(t) {
  const m = Math.floor(t / 60), s = Math.floor(t % 60);
  return `${m}:${String(s).padStart(2, '0')}`;
}

/* audio.js — efeitos sonoros sintetizados (WebAudio). Sem assets externos. */
import C from './constants.js';

let actx = null;
let master = null;
let muted = false;

function ensure() {
  if (actx) return actx;
  try {
    actx = new (window.AudioContext || window.webkitAudioContext)();
    master = actx.createGain();
    master.gain.value = C.AUDIO.master;
    master.connect(actx.destination);
  } catch (e) { actx = null; }
  return actx;
}

function noiseBuffer(sec) {
  const buf = actx.createBuffer(1, Math.floor(actx.sampleRate * sec), actx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  return buf;
}

function playOsc(type, f0, f1, dur, vol = 0.3, delay = 0) {
  if (!actx || muted) return;
  const t0 = actx.currentTime + delay;
  const o = actx.createOscillator();
  const g = actx.createGain();
  o.type = type;
  o.frequency.setValueAtTime(f0, t0);
  o.frequency.exponentialRampToValueAtTime(Math.max(1, f1), t0 + dur);
  g.gain.setValueAtTime(vol, t0);
  g.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
  o.connect(g); g.connect(master);
  o.start(t0); o.stop(t0 + dur + 0.02);
}

function playNoise(dur, vol = 0.3, filterFreq = 2000, type = 'lowpass') {
  if (!actx || muted) return;
  const t0 = actx.currentTime;
  const src = actx.createBufferSource();
  src.buffer = noiseBuffer(dur);
  const f = actx.createBiquadFilter();
  f.type = type;
  f.frequency.value = filterFreq;
  const g = actx.createGain();
  g.gain.setValueAtTime(vol, t0);
  g.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
  src.connect(f); f.connect(g); g.connect(master);
  src.start(t0); src.stop(t0 + dur + 0.02);
}

const SFX = {
  shot() { playNoise(0.12, 0.35, 3000, 'highpass'); playOsc('square', 400, 80, 0.1, 0.1); },
  hit() { playNoise(0.06, 0.2, 1200); },
  kill() { playNoise(0.25, 0.3, 600); playOsc('sawtooth', 300, 50, 0.3, 0.15); },
  explosion() { playNoise(0.6, 0.5, 400); playOsc('sine', 150, 30, 0.6, 0.4); },
  pickup() { playOsc('square', 440, 880, 0.12, 0.15); playOsc('square', 660, 1320, 0.12, 0.1, 0.08); },
  secret() { playOsc('sine', 523, 1046, 0.3, 0.2); playOsc('sine', 784, 1568, 0.3, 0.15, 0.15); },
  door() { playOsc('sawtooth', 100, 220, 0.25, 0.2); },
  hurt() { playOsc('sawtooth', 200, 60, 0.25, 0.3); },
  noammo() { playOsc('square', 200, 180, 0.08, 0.15); },
  switch() { playOsc('square', 300, 450, 0.06, 0.12); },
  death() { playNoise(1.2, 0.4, 300); playOsc('sine', 120, 20, 1.2, 0.4); },
};

window.__registerMod('audio', {
  init() { ensure(); window.__game.audio = { play: (n) => SFX[n]?.(), toggleMute: () => { muted = !muted; return muted; } }; },
});

/* retoma o contexto na primeira interação do usuário */
window.addEventListener('pointerdown', () => { if (actx && actx.state === 'suspended') actx.resume(); }, { once: true });

/* particles.js — pool de partículas (sangue, faíscas, explosão) com fade.
 * API: window.__game.particles = { burst(pos, color, n), update(dt) }.
 */
import * as THREE from 'three';

const POOL = 80;
const geo = new THREE.BoxGeometry(0.08, 0.08, 0.08);
const deadMat = new THREE.MeshBasicMaterial({ visible: false, color: 0xffffff });

const items = [];
for (let i = 0; i < POOL; i++) {
  const m = new THREE.Mesh(geo, deadMat.clone());
  m.visible = false;
  m.userData = { vel: new THREE.Vector3(), life: 0, max: 1 };
  items.push(m);
}
let cursor = 0;
let scene = null;

function burst(pos, color, n = 8, power = 3) {
  if (!scene) return;
  for (let i = 0; i < n; i++) {
    const it = items[cursor++ % POOL];
    it.visible = true;
    it.position.copy(pos);
    it.material = new THREE.MeshBasicMaterial({ color, transparent: true });
    it.material.opacity = 1;
    const v = it.userData.vel;
    v.set((Math.random() - 0.5) * power, Math.random() * power * 0.8, (Math.random() - 0.5) * power);
    it.userData.life = it.userData.max = 0.3 + Math.random() * 0.4;
    it.scale.setScalar(0.6 + Math.random() * 0.8);
    if (!it.parent) scene.add(it);
  }
}

window.__registerMod('particles', {
  init(game, engine) {
    scene = engine.scene;
    window.__game.particles = { burst, update: updateParticles };
  },
  update(dt) { updateParticles(dt); },
});

function updateParticles(dt) {
  for (const it of items) {
    if (!it.visible) continue;
    it.userData.life -= dt;
    if (it.userData.life <= 0) { it.visible = false; if (it.parent) it.parent.remove(it); continue; }
    it.position.addScaledVector(it.userData.vel, dt);
    it.userData.vel.multiplyScalar(1 - dt * 4);
    it.material.opacity = Math.max(0, it.userData.life / it.userData.max);
  }
}

/* ================================================================
   DOOM LIKE — Estética retrô de Doom (1993)
   Preto #0a0a0a, mono Consolas/Courier, vermelho-sangue #c00.
   ================================================================ */

:root {
  --doom-black: #0a0a0a;
  --doom-blood: #c00;
  --doom-blood-bright: #ff2a2a;
  --doom-green: #3cff4a;
  --doom-yellow: #ffd23c;
  --doom-blue: #3c8dff;
  --doom-text: #d0d0d0;
  --doom-muted: #7a7a7a;
  --doom-panel-bg: rgba(10, 10, 10, 0.72);
  --doom-panel-border: #333;
  --font-mono: 'Consolas', 'Courier New', Courier, monospace;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--doom-black);
  color: var(--doom-text);
  font-family: var(--font-mono);
  user-select: none;
  -webkit-user-select: none;
}

/* ---------- Canvas do jogo ---------- */
#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: var(--doom-black);
}

/* ---------- Camada CRT / scanlines ---------- */
#crt-overlay {
  position: fixed;
  inset: 0;
  z-index: 40;
  pointer-events: none;
  background: repeating-linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.06) 0px,
    rgba(255, 255, 255, 0.06) 1px,
    transparent 1px,
    transparent 3px
  );
  opacity: 0.06;
}

/* ---------- Overlays de tela cheia ---------- */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1.2rem;
  text-align: center;
  background: var(--doom-black);
}

.overlay h2 {
  font-size: 3rem;
  letter-spacing: 0.15em;
  color: var(--doom-blood-bright);
  text-shadow: 0 0 18px rgba(255, 0, 0, 0.8), 0 0 40px rgba(255, 0, 0, 0.4);
}

.hidden {
  display: none !important;
}

/* ---------- Menu ---------- */
#menu .title {
  font-size: 5rem;
  font-weight: 900;
  letter-spacing: 0.2em;
  color: var(--doom-blood);
  text-shadow:
    0 0 12px rgba(255, 0, 0, 0.9),
    0 0 40px rgba(255, 0, 0, 0.6),
    0 4px 0 #400000;
  text-transform: uppercase;
}

#menu .subtitle {
  color: var(--doom-muted);
  letter-spacing: 0.3em;
  text-transform: uppercase;
  font-size: 0.9rem;
}

#menu .controls {
  list-style: none;
  color: var(--doom-text);
  font-size: 0.85rem;
  line-height: 1.9;
  text-align: left;
  padding: 1rem 1.5rem;
  background: var(--doom-panel-bg);
  border: 1px solid var(--doom-panel-border);
  box-shadow: inset 0 0 30px rgba(255, 0, 0, 0.08);
}

#menu .controls span {
  display: inline-block;
  min-width: 7.5rem;
  color: var(--doom-blood-bright);
  font-weight: 700;
}

.start-btn {
  font-family: var(--font-mono);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: #fff;
  background: var(--doom-blood);
  border: 2px solid #500;
  padding: 0.8rem 2.5rem;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  text-shadow: 0 0 8px rgba(255, 255, 255, 0.5);
}

.start-btn:hover {
  background: var(--doom-blood-bright);
}

.start-btn:active {
  transform: scale(0.97);
}

/* ---------- HUD ---------- */
#hud {
  position: fixed;
  inset: 0;
  z-index: 20;
  pointer-events: none;
}

#hud-top {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 0.9rem 1.2rem;
}

.stat-panel {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 0.6rem;
  background: var(--doom-panel-bg);
  border: 1px solid var(--doom-panel-border);
}

.stat-label {
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  color: var(--doom-muted);
}

.stat-value {
  font-size: 1rem;
  font-weight: 700;
  min-width: 2.2rem;
  text-align: right;
  color: #fff;
}

.bar {
  position: relative;
  width: 9rem;
  height: 0.9rem;
  background: #1a1a1a;
  border: 1px solid #000;
  overflow: hidden;
}

.bar-fill {
  position: absolute;
  inset: 0;
  transform-origin: left center;
  transition: width 0.15s linear;
}

/* Barra de vida: gradiente verde -> amarelo -> vermelho (fill por largura) */
.health-fill {
  background: linear-gradient(90deg, var(--doom-green) 0%, var(--doom-yellow) 55%, var(--doom-blood-bright) 100%);
}

/* Barra de armadura: azul */
.armor-fill {
  background: linear-gradient(90deg, #1c4db0 0%, var(--doom-blue) 100%);
}

/* ---------- Mensagens ---------- */
#messages {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  padding-top: 0.2rem;
  min-height: 2.4rem;
}

#messages .msg {
  font-size: 0.8rem;
  color: var(--doom-text);
  background: rgba(0, 0, 0, 0.55);
  padding: 0.15rem 0.5rem;
  align-self: flex-start;
  animation: msg-fade 3s forwards;
}

@keyframes msg-fade {
  0%   { opacity: 0; transform: translateY(6px); }
  10%  { opacity: 1; transform: translateY(0); }
  80%  { opacity: 1; }
  100% { opacity: 0; }
}

#kills {
  font-size: 0.8rem;
  letter-spacing: 0.1em;
  color: var(--doom-blood-bright);
  background: var(--doom-panel-bg);
  border: 1px solid var(--doom-panel-border);
  padding: 0.35rem 0.7rem;
}

/* ---------- Arma (slot) ---------- */
#weapon-slot {
  position: absolute;
  left: 1rem;
  bottom: 5.2rem;
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

#weapon-name {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: #fff;
}

#weapon-key {
  font-size: 0.75rem;
  color: var(--doom-muted);
  border: 1px solid var(--doom-panel-border);
  padding: 0.15rem 0.4rem;
}

/* ---------- Munição ---------- */
#ammo {
  position: absolute;
  right: 1.2rem;
  bottom: 1rem;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.15rem;
}

#ammo-count {
  font-size: 3.2rem;
  font-weight: 900;
  line-height: 1;
  color: var(--doom-yellow);
  text-shadow: 0 0 10px rgba(255, 210, 60, 0.4);
}

#ammo-type {
  font-size: 0.7rem;
  letter-spacing: 0.25em;
  color: var(--doom-muted);
  text-transform: uppercase;
}

.panel {
  padding: 0.5rem 0.8rem;
  background: var(--doom-panel-bg);
  border: 1px solid var(--doom-panel-border);
}

/* ---------- Minimapa ---------- */
#minimap-panel {
  position: absolute;
  left: 1rem;
  bottom: 1rem;
  width: 200px;
  padding: 0.4rem;
  background: var(--doom-panel-bg);
  border: 1px solid var(--doom-panel-border);
  text-align: center;
}

.minimap-label {
  display: block;
  font-size: 0.6rem;
  letter-spacing: 0.25em;
  color: var(--doom-muted);
  margin-bottom: 0.25rem;
}

#minimap {
  width: 100%;
  height: 150px;
  background: #000;
  border: 1px solid #222;
}

/* ---------- Mira ---------- */
#crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 24px;
  height: 24px;
  transform: translate(-50%, -50%);
}

#crosshair::before,
#crosshair::after {
  content: '';
  position: absolute;
  background: var(--doom-blood-bright);
  box-shadow: 0 0 4px rgba(255, 0, 0, 0.8);
}

/* linha horizontal */
#crosshair::before {
  left: 0;
  top: 50%;
  width: 100%;
  height: 2px;
  transform: translateY(-50%);
}

/* linha vertical */
#crosshair::after {
  top: 0;
  left: 50%;
  height: 100%;
  width: 2px;
  transform: translateX(-50%);
}

/* ---------- Vinheta de dano ---------- */
#damage-vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(
    ellipse at center,
    rgba(255, 0, 0, 0) 40%,
    rgba(255, 0, 0, 0.6) 100%
  );
  opacity: 0;
  transition: opacity 0.2s ease;
}

#damage-vignette.active {
  opacity: 1;
}

/* ---------- Morte ---------- */
#dead {
  background: linear-gradient(180deg, #2a0000 0%, var(--doom-black) 60%);
}

#dead p {
  color: var(--doom-muted);
}

/* ---------- Vitória ---------- */
#complete {
  background: radial-gradient(ellipse at center, #2a1400 0%, var(--doom-black) 70%);
}

#complete h2 {
  color: var(--doom-yellow);
  text-shadow: 0 0 18px rgba(255, 210, 60, 0.8);
}

#complete-stats p {
  font-size: 0.95rem;
  line-height: 2;
  color: var(--doom-text);
}

#complete-stats span {
  color: #fff;
  font-weight: 700;
}

/* ---------- Pausa ---------- */
#paused h2 {
  color: var(--doom-text);
  text-shadow: none;
}

#paused p {
  color: var(--doom-muted);
}

