import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const file = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'js', 'level.js');
const src = readFileSync(file, 'utf8');

/* Extrai o array RAW do level.js — garante que o mapa de teste é o mapa real. */
function extractRAW() {
  const m = src.match(/const RAW = \[(.*?)\n\];/s);
  assert.ok(m, 'RAW array not found in level.js');
  const lines = [...m[1].matchAll(/^\s*'([^']+)'/gm)].map((x) => x[1]);
  assert.ok(lines.length >= 36, `esperado >=36 linhas, got ${lines.length}`);
  return lines;
}

/* Replica a normalização do level.js (padEnd + slice + força bordas) — o raw
 * permite linhas de 43 chars que são completadas com '#' em runtime. */
function normalize(rows) {
  const W = 44, H = 36;
  const out = rows.map((r) => r.padEnd(W, '#').slice(0, W).split(''));
  for (let c = 0; c < W; c++) { out[0][c] = '#'; out[H - 1][c] = '#'; }
  for (let r = 0; r < H; r++) { out[r][0] = '#'; out[r][W - 1] = '#'; }
  return out.map((row) => row.join(''));
}

const RAW = extractRAW();
const MAP = normalize(RAW);

test('mapa tem 36 linhas x 44 colunas com bordas fechadas (após normalização)', () => {
  assert.equal(MAP.length, 36);
  for (const row of MAP) {
    assert.equal(row.length, 44, `linha com ${row.length} colunas: ${row}`);
    assert.equal(row[0], '#', `borda esquerda: ${row}`);
    assert.equal(row[43], '#', `borda direita: ${row}`);
  }
  assert.equal(MAP[0].split('').every((c) => c === '#'), true, 'linha 0 toda parede');
  assert.equal(MAP[35].split('').every((c) => c === '#'), true, 'linha 35 toda parede');
});

test('RAW cru: bordas "#" no fonte e normalização não engole símbolos de jogo', () => {
  for (const row of RAW) {
    assert.ok(row.startsWith('#'), `linha RAW sem borda esquerda: ${row}`);
    assert.ok(row.endsWith('#'), `linha RAW sem borda direita no fonte: ${row}`);
    assert.ok(row.length >= 40, `linha RAW curta demais (${row.length}): ${row}`);
  }
  /* Símbolos-chave presentes no RAW têm que sobreviver à normalização (MAP). */
  for (const sym of 'PELx') {
    const rawCount = RAW.join('').split('').filter((c) => c === sym).length;
    const mapCount = MAP.join('').split('').filter((c) => c === sym).length;
    assert.equal(mapCount, rawCount, `símbolo "${sym}": RAW=${rawCount} mas MAP=${mapCount} — slice comeu célula`);
  }
});

test('existe 1 spawn P e ele tem vizinhos acessíveis (não-beco)', () => {
  const found = [];
  for (let r = 0; r < MAP.length; r++)
    for (let c = 0; c < MAP[r].length; c++)
      if (MAP[r][c] === 'P') found.push([r, c]);
  assert.equal(found.length, 1, `esperado 1 P, got ${found.length}`);
  const [r, c] = found[0];
  const open = (rr, cc) => MAP[rr] && MAP[rr][cc] && MAP[rr][cc] !== '#';
  const n = [open(r - 1, c), open(r + 1, c), open(r, c - 1), open(r, c + 1)].filter(Boolean).length;
  assert.ok(n >= 2, `spawn (${r},${c}) é beco: só ${n} vizinhos abertos`);
  /* linha do spawn deve ter corredor aberto (>=8 células não-parede) */
  const rowOpen = MAP[r].split('').filter((ch) => ch !== '#').length;
  assert.ok(rowOpen >= 8, `linha do spawn muito fechada (${rowOpen} abertas)`);
});

test('existem >=4 tochas L (visibilidade) e spawn não está "no escuro"', () => {
  let count = 0; const nearest = [];
  for (let r = 0; r < MAP.length; r++)
    for (let c = 0; c < MAP[r].length; c++)
      if (MAP[r][c] === 'L') { count++; nearest.push([r, c]); }
  assert.ok(count >= 4, `esperado >=4 tochas, got ${count}`);
  const pr = MAP.findIndex((row) => row.includes('P'));
  const pc = MAP[pr].indexOf('P');
  let minDist = Infinity;
  for (const [r, c] of nearest) minDist = Math.min(minDist, Math.hypot(r - pr, c - pc));
  assert.ok(minDist <= 8, `tocha mais próxima a ${minDist.toFixed(1)} células — spawn escuro demais`);
});

test('símbolos válidos apenas (sem caracteres desconhecidos)', () => {
  const valid = new Set('#.PDExHAm234idB~L'.split(''));
  for (const row of MAP)
    for (const ch of row)
      assert.ok(valid.has(ch), `símbolo inválido "${ch}" na linha ${row}`);
});

